/** Contract-based test harness for the compute entry point
  *
  * @param api_selected_phase incoming data port
  */
pub fn testComputeCB(api_selected_phase: Drone_Lifecycle_Governor::Lifecycle_Phase) -> HarnessResult
{
  // Initialize the app
  crate::enablement_derivation_process_enablement_derivation_initialize();

  // [PutInPorts]: Set values on the input ports
  put_selected_phase(api_selected_phase);

  // [InvokeEntryPoint]: Invoke the entry point
  crate::enablement_derivation_process_enablement_derivation_timeTriggered();

  // [RetrieveOutState]: retrieve values of the output ports via get operations and GUMBO declared local state variable
  let api_lifecycle_enablement = get_lifecycle_enablement();

  // [CheckPost]: invoke the oracle function
  if !GUMBOX::compute_CEP_Post(api_selected_phase, api_lifecycle_enablement) {
    return HarnessResult::FailedPostcondition(TestCaseError::Fail("Postcondition failed: incorrect output behavior".into()));
  }

  return HarnessResult::Passed
}

